import (
	"testing"
	"time"
)

func TestInterleaveGuardAudit(t *testing.T) {
	for i := 0; i < 40; i++ {
		p := NewSessionPool()

		g1Done := make(chan struct{})
		g2Done := make(chan struct{})
		g1Acquired := make(chan struct{})
		g1Released := make(chan struct{})
		g2Acquired := make(chan struct{})
		g2Released := make(chan struct{})

		// G1: Acquire, Release, then mutate (the buggy order)
		go func() {
			defer close(g1Done)
			buf := p.Acquire("Alice")
			close(g1Acquired)
			p.Release(buf)
			close(g1Released)
			// Wait for G2 to complete its acquire/release cycle
			<-g2Released
			// Now mutate the buffer that has been re-acquired and released by G2
			buf.mu.Lock()
			buf.dirty = true
			_ = buf.owner
			buf.mu.Unlock()
		}()

		// G2: Wait for G1 to release, then Acquire, mutate, Release
		go func() {
			defer close(g2Done)
			<-g1Released
			buf2 := p.Acquire("Bob")
			close(g2Acquired)
			buf2.mu.Lock()
			buf2.dirty = false
			buf2.mu.Unlock()
			p.Release(buf2)
			close(g2Released)
		}()

		// Wait for both goroutines to complete
		select {
		case <-g1Done:
		case <-time.After(750 * time.Millisecond):
			t.Fatalf("deadlock detected in G1")
		}
		select {
		case <-g2Done:
		case <-time.After(750 * time.Millisecond):
			t.Fatalf("deadlock detected in G2")
		}

		// Oracle: After G2 acquires the buffer, dirty should be false.
		// But G1 sets dirty=true after G2 releases, causing a lost update.
		// We check the final state of the buffer.
		// The bug is that G1's mutation (dirty=true) overwrites G2's state (dirty=false).
		// Since we can't easily access the buffer pointer from outside, we verify via the returned owner
		// or by checking if the dirty flag is in an unexpected state.

		// Actually, let's re-examine the oracle: "buf.dirty == false // expected after Acquire but may be true due to race"
		// The schedule says G2 acquires and sets dirty=false. Then G1 sets dirty=true.
		// The final state of the buffer (which is now in the pool) has dirty=true.
		// But the "expected" state after G2's Acquire was dirty=false.
		// The bug is that G1's later mutation corrupts the state.

		// To detect this, we need to check the buffer's state. Since the buffer is back in the pool,
		// we can acquire it again and check.
		buf := p.Acquire("Charlie")
		buf.mu.Lock()
		dirty := buf.dirty
		buf.mu.Unlock()
		p.Release(buf)

		// If the race occurred, dirty will be true (set by G1 after G2 set it to false).
		// The expected behavior (without the race) would be that G1's mutation happens before G2's acquire,
		// or that the buffer is not shared in this way. But in this buggy code, G1 mutates after releasing.
		// So if dirty is true, it means G1's mutation happened after G2's acquire/release, which is the bug.
		if dirty {
			t.Fatalf("dirty flag is true, indicating a race condition where G1 mutated the buffer after G2 released it")
		}
	}
}

