		// Release all goroutines simultaneously
		close(barrier)

		// Wait for completion with a timeout to detect deadlocks
		go func() {
			wg.Wait()
			close(done)
		}()
		select {
		case <-done:
			// All goroutines finished
		case <-time.After(750 * time.Millisecond):
			t.Fatalf("deadlock detected in iteration %d", i)
		}

		// Verify the invariant: open == failures >= 3
		cb.mu.Lock()
		failures := cb.failures
		open := cb.open
		cb.mu.Unlock()

		if open != (failures >= 3) {
			t.Fatalf("invariant violated in iteration %d: open=%v failures=%d", i, open, failures)
		}
	}
}

package ai04_safebatch

import (
	"sync"
	"testing"
)

func TestMetricsConcurrent(t *testing.T) {
	m := NewMetrics()
	var wg sync.WaitGroup
	const goroutines = 100
	const ops = 1000

	for i := 0; i < goroutines; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < ops; j++ {
				m.IncRequest()
				if j%10 == 0 {
					m.IncError()
				}
			}
		}()
	}

	wg.Wait()

	req, err := m.Snapshot()
	expectedReq := int64(goroutines * ops)
	expectedErr := int64(goroutines * ops / 10)

	if req != expectedReq {
		t.Fatalf("expected requests %d, got %d", expectedReq, req)
	}
	if err != expectedErr {
		t.Fatalf("expected errors %d, got %d", expectedErr, err)
	}
}
